res = os.path.join(os.path.dirname(__file__), "..", "app", "src", "main", "res")
def esc(s):
    return s.replace("&", "&amp;").replace("<", "&lt;").replace("'", "\\'").replace('"', '\\"')
for i, lang in enumerate(LANGS):
    folder = "values" if lang == "en" else "values-" + lang
    os.makedirs(os.path.join(res, folder), exist_ok=True)
    lines = ['<?xml version="1.0" encoding="utf-8"?>', "<resources>"]
    for k, v in S.items():
        assert len(v) == 8, k
        lines.append('    <string name="%s">%s</string>' % (k, esc(v[i])))
    lines.append("</resources>")
    open(os.path.join(res, folder, "strings.xml"), "w", encoding="utf-8").write("\n".join(lines) + "\n")
print(len(S), "strings x", len(LANGS))
